/**
 * 从提交事件的 OPEN 任务出发做依赖闭包：只沿未完成阻塞关系（阻塞事件未进入
 * CONTAINED/RESOLVED/CLOSED）扩展，新加入事件继续展开其 OPEN 任务。
 * 调用方持有依赖图全局锁，边集合稳定。
 */
private Set<String> computeClosure(Collection<String> seedKeys) {
    Set<String> closure = new LinkedHashSet<>(seedKeys);
    Set<String> frontier = new LinkedHashSet<>(seedKeys);
    while (!frontier.isEmpty()) {
        Set<String> next = new LinkedHashSet<>();
        for (String key : frontier) {
            Incident incident = incidents.findByKey(key).orElseThrow();
            for (IncidentTask task : tasks.listOpenByIncident(incident.id())) {
                for (Incident blocker : incidents.listBlockingIncidents(task.id())) {
                    if (!UNBLOCKING_STATUSES.contains(blocker.status())
                            && closure.add(blocker.incidentKey())) {
                        next.add(blocker.incidentKey());
                    }
                }
            }
        }
        frontier = next;
    }
    return closure;
}

/**
 * 以锁定后的事件行为权威状态重算闭包：边集合在图锁下稳定，状态取行锁读到的
 * 最新提交值；只可能相对预计算收缩（状态机只前进），不会引入未锁定的新事件。
 */
private Set<String> closureFromLocked(Map<String, Incident> lockedByKey) {
    Map<Long, Incident> lockedById = lockedByKey.values().stream()
            .collect(Collectors.toMap(Incident::id, i -> i));
    Set<String> closure = new LinkedHashSet<>(lockedByKey.keySet());
    boolean changed = true;
    while (changed) {
        changed = false;
        for (String key : List.copyOf(closure)) {
            Incident incident = lockedByKey.get(key);
            if (incident == null) {
                continue;
            }
            for (IncidentTask task : tasks.listOpenByIncident(incident.id())) {
                for (Incident blocker : incidents.listBlockingIncidents(task.id())) {
                    Incident lockedBlocker = lockedById.get(blocker.id());
                    boolean unresolved = lockedBlocker != null
                            && !UNBLOCKING_STATUSES.contains(lockedBlocker.status());
                    if (unresolved && closure.add(blocker.incidentKey())) {
                        changed = true;
                    }
                }
            }
        }
    }
    return closure;
}

