        long conflicts = results.stream().filter(ApiException.class::isInstance)
                .map(ApiException.class::cast).filter(e -> e.status().value() == 409).count();
        assertThat(successes + conflicts).isEqualTo(2);
        assertThat(successes).isGreaterThanOrEqualTo(1);

        String commanderA = incidentService.get("A").commander();
        String commanderB = incidentService.get("B").commander();
        String handoverStatus = handoverService.get("HC-1").status();
        if ("ACCEPTED".equals(handoverStatus)) {
            // 联合交接先提交：单事件转交必然失败，两事件指挥人均为 bob
            assertThat(commanderA).isEqualTo("bob");
            assertThat(commanderB).isEqualTo("bob");
        } else {
            // 单事件转交先提交：联合接受 409，A 归 carol、B 仍归 alice，无部分接管
